import sys

def solve():
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    idx = 1
    results = []

    for _ in range(t):
        a = int(data[idx])
        b = int(data[idx + 1])
        idx += 2

        remainder = a % b
        if remainder == 0:
            results.append(0)
        else:
            results.append(b - remainder)

    for res in results:
        print(res)

if __name__ == "__main__":
    solve()
